/* SVG models are rendered locally. No network calls, animation timer, or learner-data writes. */
(function(root){
'use strict';
const all=root.NET_MODELS||[];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lines=(value,max)=>{let out=[],line='';for(const word of String(value).split(/\s+/)){if((line+' '+word).trim().length>max&&line){out.push(line);line=''}if(word.length>max){if(line){out.push(line);line=''}for(let i=0;i<word.length;i+=max)out.push(word.slice(i,i+max))}else line+=(line?' ':'')+word}if(line)out.push(line);return out};
const coords={a:[26,24],b:[270,24],c:[514,24],d:[26,190],e:[270,190],f:[514,190],g:[26,356],h:[270,356],i:[514,356]};
const W=180,H=80,green='#175c4b',muted='#789087';
function svg(m,index=0){index=Math.max(0,Math.min(m.steps.length-1,index));const step=m.steps[index];const active=new Set(step.edges),hot=new Set();for(const ed of m.edges)if(active.has(ed.id)){hot.add(ed.fromId);hot.add(ed.toId)}const byId=new Map(m.nodes.map(n=>[n.id,{...n,x:coords[n.slot][0],y:coords[n.slot][1]}]));const height=Math.max(...[...byId.values()].map(n=>n.y))+H+30;const mark=m.id+'-arrow-'+index;
 const edges=m.edges.map(ed=>{const a=byId.get(ed.fromId),b=byId.get(ed.toId),peers=m.edges.filter(x=>(x.fromId===ed.fromId&&x.toId===ed.toId)||(x.fromId===ed.toId&&x.toId===ed.fromId)),rank=peers.findIndex(x=>x.id===ed.id),lane=peers.length>1?(rank-(peers.length-1)/2)*Math.min(28,54/(peers.length-1)):0;let sx,sy,tx,ty,d,lx,ly;if(a.y===b.y){let right=b.x>a.x;sx=right?a.x+W:a.x;tx=right?b.x:b.x+W;sy=ty=a.y+H/2+lane;d=`M${sx},${sy} L${tx},${ty}`;lx=(sx+tx)/2;ly=sy-7}else if(a.x===b.x){let down=b.y>a.y;sx=tx=a.x+W/2+lane;sy=down?a.y+H:a.y;ty=down?b.y:b.y+H;d=`M${sx},${sy} L${tx},${ty}`;lx=sx+(peers.length>1?(lane<0?-40:40):25);ly=(sy+ty)/2}else{let down=b.y>a.y;sx=a.x+W/2+lane;sy=down?a.y+H:a.y;tx=b.x+W/2+lane;ty=down?b.y:b.y+H;let my=(sy+ty)/2;d=`M${sx},${sy} C${sx},${my} ${tx},${my} ${tx},${ty}`;lx=(sx+tx)/2;ly=my-8+lane*1.3}
 let ux=0,uy=0;if(a.y===b.y)ux=Math.sign(tx-sx);else uy=Math.sign(ty-sy);const arrow=`${tx},${ty} ${tx-ux*9-uy*4},${ty-uy*9+ux*4} ${tx-ux*9+uy*4},${ty-uy*9-ux*4}`;const on=active.has(ed.id),label=lines(ed.label,16),lw=Math.min(115,Math.max(26,...label.map(x=>x.length*5.4+12))),lh=label.length*12+5;
 return `<g class="model-edge${on?' is-active':''}" data-edge="${esc(ed.id)}"><path d="${d}" fill="none" stroke="${on?green:muted}" stroke-width="${on?3:1.6}" opacity="${on?1:.65}"/><polygon points="${arrow}" fill="${on?green:muted}" opacity="${on?1:.65}"/><rect x="${lx-lw/2}" y="${ly-10}" width="${lw}" height="${lh}" rx="4" fill="#f5f8f2"/><text x="${lx}" y="${ly}" text-anchor="middle" font-size="10" font-weight="${on?700:500}" fill="${on?green:'#587164'}">${label.map((t,i)=>`<tspan x="${lx}" dy="${i?12:0}">${esc(t)}</tspan>`).join('')}</text></g>`}).join('');
 const nodes=[...byId.values()].map(n=>{let on=hot.has(n.id),title=lines(n.label,23),caption=lines(n.caption,28);let titleY=n.y+(title.length===1?29:22),captionY=n.y+(title.length===1?53:61);return `<g class="model-node${on?' is-active':''}" data-node="${esc(n.id)}"><rect x="${n.x}" y="${n.y}" width="${W}" height="${H}" rx="10" fill="${on?green:'#ffffff'}" stroke="${on?green:'#bfcfc0'}" stroke-width="${on?2:1.3}"/><text x="${n.x+W/2}" y="${titleY}" text-anchor="middle" font-size="12" font-weight="700" fill="${on?'#fff':'#203f35'}">${title.slice(0,2).map((t,i)=>`<tspan x="${n.x+W/2}" dy="${i?15:0}">${esc(t)}</tspan>`).join('')}</text><text x="${n.x+W/2}" y="${captionY}" text-anchor="middle" font-size="10.5" fill="${on?'#e0f39e':'#627769'}">${caption.slice(0,2).map((t,i)=>`<tspan x="${n.x+W/2}" dy="${i?12:0}">${esc(t)}</tspan>`).join('')}</text></g>`}).join('');
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 ${height}" width="720" height="${height}" role="img" aria-labelledby="${m.id}-title ${m.id}-desc" style="font-family:Arial,sans-serif"><title id="${m.id}-title">${esc(m.title)} — bước ${index+1}: ${esc(step.title)}</title><desc id="${m.id}-desc">${esc(m.nodes.map(n=>n.label+': '+n.caption).join('; '))}. ${esc(step.body)}</desc>${edges}${nodes}</svg>`;
}
function stepView(m,i){const s=m.steps[i];return `<div class="model-current" aria-live="polite" aria-atomic="true"><div class="eyebrow">BƯỚC ${i+1} / ${m.steps.length}</div><h4>${esc(s.title)}</h4><p>${esc(s.body)}</p></div>`}
function controls(m,i){return `<div class="model-controls"><button type="button" class="btn" data-model-target="${m.id}" data-model-step="${i-1}" ${i===0?'disabled':''}>← Trước</button><span class="tiny muted">${i+1} / ${m.steps.length}</span><button type="button" class="btn primary" data-model-target="${m.id}" data-model-step="${i===m.steps.length-1?0:i+1}">${i===m.steps.length-1?'Xem lại từ đầu ↻':'Bước tiếp theo →'}</button></div><div class="model-step-list" role="group" aria-label="Chọn bước của sơ đồ">${m.steps.map((s,k)=>`<button type="button" class="model-step${k===i?' selected':''}" aria-pressed="${k===i}" data-model-target="${m.id}" data-model-step="${k}"><b>${k+1}</b><span>${esc(s.title)}</span></button>`).join('')}</div>`}
function card(m){const course=(root.COURSE||[]).find(c=>c.id===m.chapter),section=course?.sections.find(s=>s.id===m.section);return `<figure class="study-model" id="model-${m.id}"><figcaption><span class="model-badge">SƠ ĐỒ CƠ CHẾ · ${m.steps.length} BƯỚC</span><h3>${esc(m.title)}</h3><p>${esc(m.intro)}</p></figcaption><div class="model-diagram" tabindex="0" role="region" aria-label="Sơ đồ ${esc(m.title)}; có thể cuộn ngang trên màn hình nhỏ">${svg(m,0)}</div><p class="model-legend"><span></span> Xanh đậm: thành phần / mũi tên đang xét. Số trên mũi tên ứng với luồng trao đổi; thứ tự diễn giải ở các nút bên dưới. Trên điện thoại có thể vuốt ngang hình.</p><div class="model-interaction">${controls(m,0)}${stepView(m,0)}</div><details class="model-details"><summary>Hiểu từng thành phần trong hình</summary><dl>${m.nodes.map(n=>`<dt>${esc(n.label)}</dt><dd>${esc(n.definition)}</dd>`).join('')}</dl></details><details class="model-details model-transcript"><summary>Đọc liên tục toàn bộ cơ chế</summary><ol>${m.steps.map(s=>`<li><strong>${esc(s.title)}</strong><p>${esc(s.body)}</p></li>`).join('')}</ol></details>${m.deep?.length?`<details class="model-details model-deep"><summary>Đi sâu vào phép biến đổi và các khóa</summary>${m.deep.map(d=>`<h4>${esc(d.title)}</h4><p>${esc(d.body)}</p>`).join('')}</details>`:''}<div class="model-example"><strong>Ví dụ đi hết mô hình</strong><p>${esc(m.example)}</p></div><div class="model-limits"><strong>Giới hạn của hình — đừng suy ra quá mức</strong><p>${esc(m.limits)}</p></div><details class="model-details"><summary>Điểm dễ nhầm & tự kiểm tra</summary><ul>${m.mistakes.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><strong>${esc(m.check.question)}</strong><details class="model-check"><summary>Xem giải thích</summary><p>${esc(m.check.answer)}</p></details></details><p class="source">Sơ đồ và phần diễn giải tự biên soạn bổ trợ, không phải ảnh nguyên bản. Nguồn kiến thức: ${esc(course?.file||'')} · trang PDF ${section?section.from+'–'+section.to:''} · mục ${esc(m.section)}.${m.refs.length?' Đối chiếu mở rộng: '+m.refs.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Tài liệu chuẩn ${i+1} ↗</a>`).join(' · '):''}</p></figure>`}
function renderSection(chapter,section){return all.filter(m=>m.chapter===chapter&&m.section===section).map(card).join('')}
function catalog(selected='all'){let cs=root.COURSE||[];return `<div class="model-catalog-intro"><div class="eyebrow">THƯ VIỆN MÔ HÌNH</div><h1>Nhìn thấy cơ chế.<br>Hiểu từng bước.</h1><p class="intro">${all.length} sơ đồ, ${all.reduce((n,m)=>n+m.steps.length,0)} bước giải thích. Chọn một mô hình để đọc ngay trong bài: xem luồng dữ liệu, vai trò các khóa, điều kiện hoạt động và những gì hình chưa mô tả.</p><label>Lọc theo bài <select id="modelChapterFilter"><option value="all">Tất cả bài học</option>${cs.map(c=>`<option value="${esc(c.id)}" ${selected===c.id?'selected':''}>Bài ${esc(c.id)} · ${esc(c.title)}</option>`).join('')}</select></label></div><div class="grid model-catalog-grid">${all.map(m=>`<a class="card chapter-card model-catalog-card" data-model-chapter="${m.chapter}" ${selected!=='all'&&selected!==m.chapter?'hidden':''} href="#lesson/${m.chapter}/${encodeURIComponent(m.section)}/${m.id}"><div class="chapter-top"><span class="chapter-number">BÀI ${esc(m.chapter)}</span><span class="chip">${m.steps.length} bước</span></div><h3>${esc(m.title)}</h3><p>${esc(m.intro)}</p><div class="chapter-meta"><span>Mục ${esc(m.section)}</span><span>Xem mô hình ↗</span></div></a>`).join('')}</div>`}
function selectStep(id,index,doc=document){const m=all.find(x=>x.id===id);if(!m||!Number.isInteger(index)||index<0||index>=m.steps.length)return false;const figure=doc.getElementById('model-'+id);if(!figure)return false;figure.querySelector('.model-diagram').innerHTML=svg(m,index);const panel=figure.querySelector('.model-interaction');const oldFocus=doc.activeElement;const hadFocus=oldFocus&&panel.contains(oldFocus);panel.innerHTML=controls(m,index)+stepView(m,index);if(hadFocus){const target=panel.querySelector(`.model-step[data-model-step="${index}"]`);target?.focus({preventScroll:true})}return true}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-model-target]');if(b)selectStep(b.dataset.modelTarget,Number(b.dataset.modelStep))});
document.addEventListener('change',ev=>{if(ev.target.id==='modelChapterFilter'){for(const card of document.querySelectorAll('[data-model-chapter]'))card.hidden=ev.target.value!=='all'&&card.dataset.modelChapter!==ev.target.value}});
root.ModelUI={renderSection,catalog,selectStep,svg};
})(window);
